\label{lem:coupling}
 Let~$U$ be uniformly distributed on the interval~$(0,1)$ and independent of~$X$. Set~${Q_k(X)=P(Y=k|X)}$ and define the variable 
 \begin{equation}\label{eq:y-representation}
 \widetilde Y = f(X,U)\vcentcolon=\min\left\lbrace k\in \{1,\ldots, K\} \colon\sum_{j=1}^k Q_j(X)>U\right\rbrace.
 \end{equation}
Then~$(\widetilde Y,X)$ and~$(Y,X)$ are identically distributed.

\label{lem:x-ind-y}  
        (i)~The variables~$X$ and~$Y$ are independent if and only if~$Y$ and~$Y'$ are independent.
        (ii)~There exists~$f\colon \mathcal{H}\to \{1,\ldots, K\}$ such that~$Y=f(X)$, if and only if there is a function~$\ell\in\mathcal{L}_Y$ such that~$Y=\ell(Y')$.

\label{rem:frobenius}
    It can be readily verified that
   ~$$
    p_{i,j}-p_{i}p_{j}=\mathrm{Cov}(Q_i(X),Q_j(X)).
   ~$$
    Thus, setting~$Q(X)=(Q_1(X),\ldots, Q_K(X))'$ and defining~$D=\mathrm{diag}(p_{1},\ldots, p_{K})$, we may alternatively write
    \begin{align}
    (K-1)\psi(X,Y)&=\|D^{-1/2}\,\mathrm{Var}(Q(X))\,D^{-1/2}\|_F^2\label{eq:repfrob}\\
    &=\mathrm{vec}(\mathrm{Var}(Q(X)))' \  (D\otimes D)^{-1} \ \mathrm{vec}(\mathrm{Var}(Q(X))).\label{eq:repkron}
    \end{align}
     We will refer later to the alternative representations~\eqref{eq:repfrob} and \eqref{eq:repkron}.

\label{le:suff2}
Let~$\mathcal{V}_k=\{(x,u)\in \mathcal{H}\times (0,1)\colon f(x,u)=k\}$. If we have \begin{equation}
\label{eq:condsuff2}
P\left((X,U)\in \bigcup_{k=1}^K\partial\mathcal{V}_k\right)=0,
\end{equation}
then Assumption~\ref{ass:convergence} holds.

\label{thm:clt}
    Assume that~$X$ and~$Y$ are independent, set
\begin{equation*}
P_n=\sqrt{n}\,\mathrm{vec}\Big(((\widehat p_{k,l} -\widehat p_{k}\widehat{ q_{l}}))_{k,l=1}^{K-1}\Big),
\end{equation*}
     and let ~$\Sigma_n=\mathrm{Var}(P_n|X_1,\ldots,X_n)$.

\noindent     (i) Then under Assumption~\ref{ass:convergence} 
     \begin{align*}
&\Sigma_n((k_1,l_1), (k_2,l_2))\\
&\qquad=p_{k_1}p_{l_1}p_{k_2}p_{l_2}(1+W_{n})\\
        &\qquad\quad- p_{k_1}p_{l_1}p_{l_2}(1\lbrace k_1=k_2\rbrace + W_{n} 1\lbrace l_1=k_2\rbrace)\\
        &\qquad\quad-p_{k_1}p_{l_1}p_{k_2}(1\lbrace l_1=l_2\rbrace + W_{n} 1\lbrace k_1=l_2\rbrace)\\
        &\qquad\quad+p_{k_1}p_{l_1}(1\lbrace k_1=k_2, l_1=l_2\rbrace + W_{n} 1\lbrace k_1=l_2, l_1=k_2\rbrace)+o_P(1), 
     \end{align*}
     with
\begin{equation}\label{eq:W1n}
W_{n}\vcentcolon=\frac{1}{n}\sum_{i=1}^n I\{N(N(i))=i\}.
\end{equation}
(ii) Let Assumption~\ref{ass:neighbour-degree} hold and suppose that we have some~$b>0$ such that
\begin{equation}\label{eq:lambdamin}
P(W_n\leq 1-b)\to 1.
\end{equation}
Then for large enough~$n$ the matrix~$\Sigma_n$ is invertible and
    \begin{equation*}
    \mathcal{I}_n^0\vcentcolon=P_n'\Sigma_n^{-1}P_n \stackrel{\mathcal{D}}{\longrightarrow} \chi^2((K-1)^2),\quad (n\to\infty).
    \end{equation*}
     If~$\widehat \Sigma_n$ denotes the empirical analogue to~$\Sigma_n$ with~$p_k$ replaced by their estimators~$\widehat p_k$, then we also have 
\begin{equation*}
    \mathcal{I}_n\vcentcolon=P_n'\widehat\Sigma_n^{-1}P_n \stackrel{\mathcal{D}}{\longrightarrow} \chi^2((K-1)^2).
    \end{equation*}

To clarify the relationship between~$\mathcal{I}_n$ and~$\widehat\psi(X,Y)$, we refer to the representation of~$\psi(X,Y)$ given in \eqref{eq:repkron}. Observe that~$P_n/\sqrt{n}$ serves as the sample analogue of~$\mathrm{vec}(\mathrm{Var}(Q^{[-K]}(X)))$, where~$Q^{[-K]}(X)$ excludes the redundant component
 \begin{equation*}
     Q_K(X) = 1 - Q_1(X) - \cdots - Q_{K-1}(X)
 \end{equation*}
 from~$Q(X)$. To account for dependencies between the coordinates of~$P_n$ and to obtain a pivotal limit distribution, the weighting matrix of the quadratic form is suitably adjusted.

\label{lem:limitW1n}
    Suppose~$\mathcal{H}=\mathbb{R}^d$ and assume that~$X_i$ have a continuous density. Then we have~$W_{n}\stackrel{\mathcal{P}}{\longrightarrow} \gamma_d\vcentcolon=\frac{\mathrm{vol}(\mathcal{S}_d)}{\mathrm{vol}(\mathcal{S}_d\cup 
    \mathcal{S}_{1,d})}$, where~$\mathcal{S}_d$ is the unit-sphere in~$\mathbb{R}^d$ and~$\mathcal{S}_{1,d}$ is an affine shift of~$\mathcal{S}_d$ by distance 1. It holds that~$\gamma_d\in (1/2, 2/3]$, with~$\gamma_1=2/3$ and~$\gamma_d\searrow  1/2$ for~$d\to\infty$.

\label{cor:consistent-test}
Let Assumptions~\ref{ass:convergence} and~\ref{ass:neighbour-degree} hold. Assume that~$X$ and~$Y$ are not independent. Then
$\mathcal{I}_n\stackrel{\mathcal{P}}{\longrightarrow}\infty$  as~$n\to\infty$. The divergence rate is of order  $\sqrt{n}$.

\label{lem:convergence}
    (i) Under Assumption~\ref{ass:convergence}  it holds for all~${k,l}$ that
    \begin{equation*}
        \widehat p_{k,l}\stackrel{\mathcal{P}}{\longrightarrow} p_{k,l},\quad (n\to\infty).
    \end{equation*}
    \par (ii) If we additionally impose \eqref{ref:assasconv}, then convergence in probability can be strengthened to almost sure convergence.

Since
    \begin{equation*}
        \mathbb{E}\,\left(1\lbrace Y_i =k\rbrace\right)=p_k\qquad\text{and}\qquad \mathbb{E}\,\left(1\lbrace Y_{N(i)} =l\rbrace\right)=p_l,
    \end{equation*}
    and~${Y_i, Y_{N(i)}}$ are independent (unconditionally and conditionally on~$\mathcal{G}_n$), we get that
    \begin{equation*}
        \mathbb{E}\,\left((1\lbrace Y_i =k\rbrace - p_k)(1\lbrace Y_{N(i)} =l\rbrace - p_l)|\mathcal{G}_n\right) = 0.
    \end{equation*}
    As a consequence, it follows that
    \begin{align*}
    &\operatorname{Cov}\Big((1\lbrace Y_i=k_1\rbrace -p_{k_1})(1\lbrace Y_{N(i)}=l_1\rbrace -p_{l_1}),\\ &\qquad\qquad (1\lbrace Y_j=k_2\rbrace -p_{k_2})(1\lbrace Y_{N(j)}=l_2\rbrace -p_{l_2})|\mathcal{G}_n\Big)\\
        &= \mathbb{E}\,\big((1\lbrace Y_i=k_1\rbrace -p_{k_1})(1\lbrace Y_{N(i)}=l_1\rbrace -p_{l_1})\times\\
        &\qquad\qquad
        (1\lbrace Y_j=k_2\rbrace -p_{k_2})(1\lbrace Y_{N(j)}=l_2\rbrace -p_{l_2})|\mathcal{G}_n\big).
    \end{align*}
    Expanding these products, we obtain~16 summands, depending the combinations of~$i$ and~$j$. We defer these tedious calculations to Supplement~\ref{sec:calculation-sigma}. Summing over these terms yields~$\Sigma_n$.

\label{lem:clt}
    We denote~$\Sigma_{g,n}=\mathrm{Var}(P_n|\mathcal{G}_n=g)$ and let~$\mathcal{K}_n, n\geq 1$, be a sequence of collections of nearest neighbour graphs~$g$ with~$n$ vertices, such that
    \begin{equation*}
        \sup_{g\in \mathcal{K}_n}\mathrm{deg}(g)= o\left(n^{1/4}\right)
    \end{equation*}
    and such that the coefficient~$W_{n}$ defined in \eqref{eq:W1n} and corresponding to~$g$ is at most~${1-b/2}$. Then, for any vector~$c$ on the~$(K-1)^2$-dimensional unit sphere it holds that
    \begin{equation*}
        \sup_{g\in\mathcal K_n}\sup_{z\in\mathbb{R}} \left|P\left(c'\Sigma_{g,n}^{-1/2}P_n\leq z\middle| \mathcal G_n = g\right)-\Phi(z)\right|\to 0,\quad (n\to \infty).
    \end{equation*}

By Lemma~\ref{lem:x-ind-y}, there are indices~${k,l}$ with~${p_{k,l}\neq p_kp_l}$. By Lemma~\ref{lem:convergence}, it follows that
    \begin{equation*}
        |\sqrt{n} (\widehat p_{k,l}-\widehat p_k\widehat q_l)|\stackrel{\mathcal{P}}{\longrightarrow} \infty.
    \end{equation*}
    Since~$\widehat\Sigma_n$ is asymptotically regular, the test statistic diverges as well.

\label{lem:conditional}
Under the assumptions of Theorem~\ref{thm:general-norms} it holds that
\begin{equation*}
    \|\operatorname{Var}(Q(X,Z))\|\geq \|\operatorname{Var}(Q(X))\|,
\end{equation*}
with equality if and only if~$Y$ is independent of $Z$ conditionally on $X$.

Since~${Q(X,Z)=(P(Y=1|X,Z),\ldots, P(Y=K|X,Z))'}$, it holds that
\begin{equation*}
    \mathbb{E}\,(Q(X,Z)|X)=Q(X).
\end{equation*}
By the law of total variance, we have
\begin{align*}
    &\|\operatorname{Var}(Q(X,Z))\|\\
    &\quad = \|\operatorname{Var}(\mathbb{E}\,(Q(X,Z)|X)) + \mathbb{E}\,(\operatorname{Var}(Q(X,Z)|X))\|\\
    &\quad = \|\operatorname{Var}(Q(X)) + \mathbb{E}\,(\operatorname{Var}(Q(X,Z)|X))\|\\
    &\quad\geq \|\operatorname{Var}(Q(X))\|,
\end{align*}
because~${\|\cdot\|}$ is monotone and (conditional) covariance matrices as well as their expectations are PSD. Moreover, by strict monotonicity of~${\|\cdot\|}$, equality holds if and only if~${\operatorname{Var}(Q(X,Z)|X)}$ is almost surely equal to the zero matrix. But this is only the case if~$Q(X,Z)$ is~$X$ measurable, implying that~$Y$ is independent of $Z$ conditionally on $X$.

\ref{it:m1}: Since~$\gamma$ maps into the interval~${\lbrack0,1\rbrack}$, we only need to check that the quotient of the norms remains inside its domain. Non-negativity is obvious. As for the upper bound, it is easy to see that~${Q(Y)=Q(X,Y)}$ and therefore, by Lemma~\ref{lem:conditional} with~${Z=Y}$, the denominator in~\eqref{eq:norm-measure} is larger or equal than the numerator.
    \par \ref{it:m2}: The covariance matrix~${\operatorname{Var}(Q(X))}$ is the zero matrix if and only if the conditional distribution of~$Y$ given~$X$ does not actually depend on~$X$, meaning that~$X$ and~$Y$ are independent.

        \par \ref{it:m3}: If~$Y$ is $\sigma(X)$-measurable, then~${Q(X)=Q(Y)}$ and therefore~${\psi_{\|\cdot\|,\gamma}=1}$. On the other hand, if~$Y$ is not $\sigma(X)$-measurable, then~$Y$ is not independent of itself given~$X$ and therefore by Lemma~\ref{lem:conditional}
    \begin{equation*}
        \|\operatorname{Var}(Q(X))\|<\|\operatorname{Var}(Q(X,Y))\|=\|\operatorname{Var}(Q(Y))\|.
    \end{equation*}

    \par\ref{it:m4} and~\ref{it:m5}: These are direct consequences of Lemma~\ref{lem:conditional} and the monotonicity of~$\gamma$.

    \par \ref{it:m1-conditional}: By~\ref{it:m1} we have~${\psi_{\|\cdot\|,\gamma}((X,Z),Y)\leq 1}$. Together with~\ref{it:m4}, this implies the statement.

    \par \ref{it:m2-conditional}: This follows directly from~\ref{it:m5} and monotonicity of~$\gamma$.

    \par\ref{it:m3-conditional}: By~\ref{it:m3}, numerator and denominator are equal if and only if~$Y$ is~$\sigma(X,Z)$-measurable.

\label{lem:convergence-distribution-1}
Suppose Assumption~\ref{ass:convergence} holds. Then for~$n\to\infty$, we have
\begin{equation*}
    (Y_1,Y_{N(1)}, Y_2, Y_{N(2)})\stackrel{\mathcal{D}}{\longrightarrow} (Y_1, Y_1', Y_2, Y_2').
\end{equation*}

Since we are dealing with discrete data Assumption~\ref{ass:convergence}~(a)
is equivalent to
\begin{equation}
1\{f(X_{N(1)},u)=k\}\stackrel{P}{\to} 1\{f(X_1,u)=k\}\label{eq:altcond}
\end{equation} 
for almost all~$u$ and for all~$1\leq k\leq K$.
    By Part~(ii) of Lemma~\ref{lem:neighbour-convergence} we get
\begin{align*}
    &P(Y_1=k_1, Y_{N(1)} =l_1, Y_2=k_2, Y_{N(2)}=l_2)\\
    &\quad = P(Y_1=k_1, f(X_{N(1)}, U_1') = l_1, 
    Y_2=k_2, f(X_{N(2)}, U_2') = l_2)+o(1),
\end{align*}
where~$U_i'\stackrel{iid}{\sim} \mathcal U(0,1)$ and independent of all other variables. Hence,
\begin{align*}
    &P(Y_1=k_1, f(X_{N(1)}, U_1') = l_1, 
    Y_2=k_2, f(X_{N(2)}, U_2') = l_2)\\
    & = \int_{\lbrack 0,1\rbrack^2} \mathbb{E}\,\left( 1\{Y_1=k_1, Y_2=k_2\} 1\{f(X_{N(1)}, u) = l_1\} 1\{f(X_{N(2)}, v) = l_2)\}\right)dudv.
\end{align*}
Due to \eqref{eq:altcond}, the integrand converges in probability to
$$
1\{Y_1=k_1, Y_2=k_2\} 1\{f(X_1, u) = l_1\} 1\{f(X_2, v) = l_2\}
$$
and since it is bounded, the limit can pushed inside integral and expected value, yielding the claimed weak convergence.

Alternatively, assume that Assumption~\ref{ass:convergence}~(b) holds.
    Let~${\mathbf{X}_n\vcentcolon=(X_1,\ldots, X_n)}$ and define~${\mathbf{x}=(x_1,\ldots,x_n)\in\mathcal{H}^n}$. We have that
    \begin{align}
        &P(Y_1=k_1, Y_{N(1)}=l_1, Y_2=k_2, Y_{N(2)}=l_2)\nonumber\\
        &\quad = \int_{\mathcal{H}^n} P\big(f(x_1,U_1)=k_1, f(x_{n(1)},U_{n(1)})=l_1,\nonumber\\ 
        &\qquad\qquad f(x_2,U_2)=k_2, f(x_{n(2)},U_{n(2)})=l_2\big)~dP_{\mathbf{X}_n}(\mathbf{x}).\label{eq:integral-prob}
    \end{align}
    We split the integral over regions
\begin{equation}
R_1\vcentcolon=\{\mathbf{x}\colon |\{1,2,n(1),n(2)\}|=4\}\quad \text{and}\quad R_2\vcentcolon=R_1^c.
\end{equation}
By the second part of Lemma~\ref{lem:neighbour-convergence}, it follows that
    \begin{equation*}
        P(\mathbf{X}_n\in R_2)\leq P(N(1)=2)+P(N(2)=1)+P(N(1)=N(2))=o(1).
    \end{equation*}
Since the~$U_i$ are independent of each other and of the~$X_i$, the integrand in~\eqref{eq:integral-prob} factorizes on~$R_1$, i.e.\ we may write    
\begin{align*}
        &P(Y_1=k_1, Y_{N(1)}=l_1, Y_2=k_2, Y_{N(2)}=l_2)\\
        &\quad = \int_{R_1} P(f(x_1,U_1)=k_1)P( f(x_{n(1)},U_{1}')=l_1)\\ &\qquad\quad P(f(x_2,U_2)=k_2)P(f(x_{n(2)},U_{2}')=l_2)~dP_{\mathbf{X}_n}(\mathbf{x})+o(1)\\
        &\quad = \int_{\mathcal H^n} Q_{k_1}(x_1)Q_{l_1}(x_{n(1)}) Q_{k_2}(x_2)Q_{l_2}(x_{n(2)})~dP_{\mathbf{X}_n}(\mathbf{x}) + o(1)\\
        &\quad = \int_{\mathcal H^n} Q_{k_1}(x_1)Q_{l_1}(x_{1}) Q_{k_2}(x_2)Q_{l_2}(x_{2})~dP_{\mathbf{X}_n}(\mathbf{x})\\
        &\qquad + \int_{\mathcal H^n} Q_{k_1}(x_1)(Q_{l_1}(x_{n(1)})-Q_{l_1}(x_{1})) Q_{k_2}(x_2)Q_{l_2}(x_{2})~dP_{\mathbf{X}_n}(\mathbf{x})\\
        &\qquad + \int_{\mathcal H^n} Q_{k_1}(x_1)Q_{l_1}(x_{n(1)}) Q_{k_2}(x_2)(Q_{l_2}(x_{n(2)})-Q_{l_2}(x_{2}))~dP_{\mathbf{X}_n}(\mathbf{x}) + o(1)
        \\
        &\quad =:T_{1,n}+T_{2,n}+T_{3,n}+o(1).
    \end{align*}
    Now we note that
    $T_{1,n}=P(Y_1=k_1,Y_1'=l_1,Y_2=k_2,Y_2'=l_2)$. Moreover, we have
\begin{align*}
    |T_{2,n}|&\leq \int_{\mathcal H^n}|Q_{l_1}(x_{n(1)})-Q_{l_1}(x_{1})| ~dP_{\mathbf{X}_n}(\mathbf{x})=\mathbb{E}\,|Q_{\ell_1}(X_{N(1)})-Q_{\ell_1}(X_{1})|.
\end{align*}
By Assumption~\ref{ass:convergence}~(b) we have that $Q_{\ell_1}(x)$ is $P_X$-almost surely continuous, and hence by Lemma~\ref{lem:neighbour-convergence}~(i) it follows that $Q_{\ell_1}(X_{N(1)})\to Q_{\ell_1}(X_{1})$. By dominated convergence we conclude that $T_{2,n}\to 0$ and by the same arguments we also get~$T_{3,n}\to 0$.

\label{lem:combes}
    Let~$\mathcal{X}_1,\ldots, \mathcal{X}_n$ be a collection of arbitrary metric spaces and set~${\mathcal{X}=\mathcal{X}_1\times\ldots\times\mathcal{X}_n}$. Let~$\mathcal{Y}\subset \mathcal{X}$ and let~$X$ be an~$\mathcal{X}$-valued random variable. Denote~${p=P(X\notin \mathcal Y)}$.
    If~$f:\mathcal{X}\to\mathbb{R}$ is such that for all pairs~$x,y\in\mathcal Y$ which are only distinct in the~$i$-th coordinate we have \begin{equation}\label{eq:bounded-differences}
        |f(x)-f(y)|\leq c_i,
    \end{equation}
    then it holds that \begin{equation}\label{eq:combes}
        P(|f(X)-\mathbb{E}\,\left(f(X)|X\in\mathcal Y\right)|\geq \varepsilon)\leq 2p+2\exp\left(-\frac{2\left(\varepsilon-p\sum_{i=1}^n c_i\right))^2}{\sum_{i=1}^n c_i^2}\right).
    \end{equation}

(i) We consider
    \begin{align*}
        \operatorname{Var}\left(\widehat p_{k,l}\right) &= \operatorname{Var}\left(\frac{1}{n}\sum_{i=1}^n 1\lbrace Y_i = k, Y_{N(i)}=l\rbrace\right)\\
         &=  \frac{1}{n^2}\sum_{i=1}^n\operatorname{Var}\left(1\lbrace Y_i = k, Y_{N(i)}=l\rbrace\right)\\
        &\qquad + \frac{1}{n^2}\sum_{i\neq j}^n \operatorname{Cov}\left(1\lbrace Y_i = k, Y_{N(i)}=l\rbrace, 1\lbrace Y_j = k, Y_{N(j)}=l\rbrace\right)\\
        &\leq \frac{1}{n}\operatorname{Var}\left(1\lbrace Y_1 = k, Y_{N(1)}=l\rbrace\right)\\
        &\qquad+|\operatorname{Cov}\left(1\lbrace Y_1 = k, Y_{N(1)}=l\rbrace, 1\lbrace Y_2 = k, Y_{N(2)}=l\rbrace\right)|.
    \end{align*}
    The first term is~$O(1/n)$. The second term is
    \begin{align*}
        &|P\left( Y_1 = k, Y_{N(1)}=l, Y_2 = k, Y_{N(2)}=l \right)\\
        &\qquad -P\left(  Y_1 = k, Y_{N(1)}=l \right)P\left(  Y_2 = k, Y_{N(2)}=l \right)|,
    \end{align*}
 and by Lemma~\ref{lem:convergence-distribution-1}  it converges to
  \begin{align*}
        &|P\left( Y_1 = k, Y_1'=l, Y_2 = k, Y_2'=l \right)\\
        &\qquad -P\left(  Y_1 = k, Y_1'=l \right)P\left(  Y_2 = k, Y_2'=l \right)|.
    \end{align*}
    By independence of~$(Y_1,Y_1')$ 
     and~$(Y_2,Y_2')$ the last expression is equal to zero. Likewise, it follows from Assumption~\ref{ass:convergence} that~$\mathbb{E}\,  \widehat p_{k,l}\to p_{k,l}$, and thus (i) follows.

    \par (ii) We use Lemma~\ref{lem:combes} with~$\mathcal X=\mathcal{H}^n\times\{1,\ldots,K\}^n$,
    \begin{equation*}
        f(x_1,\ldots, x_n, y_1,\ldots, y_n)=\frac{1}{n}\sum_{j=1}^n 1\{y_j=k,y_{n(j)}=l\},
    \end{equation*}
    and
    \begin{equation*}
        \mathcal Y = \lbrace (x_1,\ldots, x_n,y_1,\ldots, y_n): l_n\leq k_n\rbrace.
    \end{equation*}
    We remark that~$\widehat p_{k,l}=f(X_1,\ldots, X_n,Y_1,\ldots, Y_n)$. 

    Consider some tuple~$(\mathbf{x},\mathbf{y})=(x_1,\ldots, x_n,y_1,\ldots, y_n)\in \mathcal Y$ and let~$(\mathbf{x}^{(i)},\mathbf{y})$ and~$(\mathbf{x},\mathbf{y}^{(i)})$ be perturbations of~$(\mathbf{x},\mathbf{y})$ where~$x_i$ is replaced by~$x_i'$ and~$y_i$ by~$y_i'$, while all other coordinates remain unchanged. Moreover, assume that~$(\mathbf{x}^{(i)},\mathbf{y})$ and~$(\mathbf{x},\mathbf{y}^{(j)})$ are also in~$\mathcal Y$. It follows that 
   ~$$
    |f(\mathbf{x},\mathbf{y})-f(\mathbf{x}^{(i)},\mathbf{y})|\leq \frac{1}{n}\sum_{j=1}^n 1\{n_\mathbf{x}(j)\neq n_{\mathbf{x}^{(i)}}(j)\}\leq \frac{2 k_n}{n},
   ~$$
    and
 ~$$
    |f(\mathbf{x},\mathbf{y})-f(\mathbf{x},\mathbf{y}^{(i)})|\leq \frac{1}{n}\sum_{j=1}^n (1\{j=i\}+1\{n(j)=i\})\leq \frac{1+ k_n}{n}.
   ~$$  
Therefore,~\eqref{eq:bounded-differences} holds with~${c_i=2k_n/n}$. Using~\eqref{eq:combes}, we obtain
    \begin{align*}
        & P\left(|\widehat p_{k,l}-\mathbb{E}\, (\widehat p_{k,l}|(X_1,\ldots,X_n,Y_1,\ldots,Y_n)\in\mathcal Y_n)|\geq \varepsilon\right)\\
        &\quad\leq 2P(L_n\geq k_n) + 2\exp\left(-\frac{2(\varepsilon-2k_nP(L_n\geq k_n))^2}{4k_n^2/n}\right).
    \end{align*}
    By Assumption~\eqref{ref:assasconv}, this term is summable over~$n$ and hence by the Borel-Cantelli lemma it follows that
    \begin{equation*}
        \widehat p_{k,l}-\mathbb{E}\, (\widehat p_{k,l}|(X_1,\ldots,X_n,Y_1,\ldots,Y_n)\in\mathcal Y_n)\stackrel{a.s.}{\longrightarrow} 0.
    \end{equation*}
Likewise, using dominated convergence and again the Borel-Cantelli lemma we get
    \begin{equation*}
        \mathbb{E}\, (\widehat p_{k,l}|(X_1,\ldots,X_n,Y_1,\ldots,Y_n)\in\mathcal Y_n)-\mathbb{E}\,(\widehat p_{k,l})\stackrel{a.s.}{\longrightarrow} 0.
    \end{equation*}
    As already shown above, it holds that~${\mathbb{E}\, \widehat p_{k,l}\to p_{k,l}}$, which completes the proof.

\label{lem:determinant}
    It holds that
    \begin{align*}    \mathrm{det}\left(\Sigma_{n}\right)&=\left(1+W_{n}\right)^{K(K-1)/2}\left(1-W_{n}\right)^{(K-1)(K-2)/2}\prod_{i=1}^{K} p_i^{2(K-1)}.
    \end{align*}

\label{thm:rinott}[\cite{rinott_normal_1994}, Thm. 2.2]
 Let~$V_1,\ldots,V_n$ be random variables having a dependence graph whose maximal degree is strictly less than~$k$ and satisfy
 \begin{enumerate}
 \item~$|V_i|\leq~B$ almost surely for~$i=1,\ldots,n$,
 \item~$\mathbb{E}\,  V_i =0$ and
 \item~$\operatorname{Var}(\sum_{i=1}^n V_i)=1$.
 \end{enumerate}
 Then
 \begin{equation}\label{eq:rinott}
 \left|P\left(\sum_{i=1} V_i\leq~z\right)-\Phi(z)\right|\leq~\sqrt{\frac{1}{2\pi}}kB+16\sqrt{n}k^{3/2}B^2+10nk^2B^3.
 \end{equation}
